// Families are explicit allowlisted names. Custom family names are generated by
// the server and never taken from an uploaded filename or font metadata.
const weights = (...values) => values;
const italicFamilies = new Set([
  "Sarabun",
  "Prompt",
  "Kanit",
  "Bai Jamjuree",
  "Chakra Petch",
  "Krub",
  "K2D",
  "Taviraj",
  "Trirong",
  "Mali",
  "Noto Sans",
  "Inter",
]);
const sans = [
  [
    "IBM Plex Sans Thai",
    "ibm-plex-sans-thai",
    weights(100, 200, 300, 400, 500, 600, 700),
  ],
  [
    "Noto Sans Thai",
    "noto-sans-thai",
    weights(100, 200, 300, 400, 500, 600, 700, 800, 900),
  ],
  ["Sarabun", "sarabun", weights(100, 200, 300, 400, 500, 600, 700, 800)],
  ["Anuphan", "anuphan", weights(100, 200, 300, 400, 500, 600, 700)],
  ["Prompt", "prompt", weights(100, 200, 300, 400, 500, 600, 700, 800, 900)],
  ["Kanit", "kanit", weights(100, 200, 300, 400, 500, 600, 700, 800, 900)],
  ["Bai Jamjuree", "bai-jamjuree", weights(200, 300, 400, 500, 600, 700)],
  ["Chakra Petch", "chakra-petch", weights(300, 400, 500, 600, 700)],
  ["Krub", "krub", weights(200, 300, 400, 500, 600, 700)],
  ["K2D", "k2d", weights(100, 200, 300, 400, 500, 600, 700, 800)],
  ["Athiti", "athiti", weights(200, 300, 400, 500, 600, 700)],
  ["Mitr", "mitr", weights(200, 300, 400, 500, 600, 700)],
];
const serif = [
  [
    "Noto Serif Thai",
    "noto-serif-thai",
    weights(100, 200, 300, 400, 500, 600, 700, 800, 900),
  ],
  ["Pridi", "pridi", weights(200, 300, 400, 500, 600, 700)],
  ["Maitree", "maitree", weights(200, 300, 400, 500, 600, 700)],
  ["Taviraj", "taviraj", weights(100, 200, 300, 400, 500, 600, 700, 800, 900)],
  ["Trirong", "trirong", weights(100, 200, 300, 400, 500, 600, 700, 800, 900)],
  ["Chonburi", "chonburi", weights(400)],
];
const display = [
  ["Mali", "mali", weights(200, 300, 400, 500, 600, 700)],
  ["Itim", "itim", weights(400)],
];
export const requestedFonts = [
  ...sans.map((font) => [...font, "sans-serif"]),
  ...serif.map((font) => [...font, "serif"]),
  ...display.map((font) => [...font, "handwriting"]),
].map(([family, slug, availableWeights, category]) => ({
  family,
  label: family,
  package: `@fontsource/${slug}`,
  slug,
  weights: availableWeights,
  styles: italicFamilies.has(family) ? ["normal", "italic"] : ["normal"],
  category,
  license: "OFL-1.1",
  source: `https://fontsource.org/fonts/${slug}`,
  custom: false,
}));

export const builtInFonts = [
  ...requestedFonts,
  ...[
    ["Noto Sans", "noto-sans"],
    ["Inter", "inter"],
  ].map(([family, slug]) => ({
    family,
    label: family,
    slug,
    package: `@fontsource/${slug}`,
    weights: [100, 200, 300, 400, 500, 600, 700, 800, 900],
    styles: ["normal", "italic"],
    category: "sans-serif",
    license: "OFL-1.1",
    source: `https://fontsource.org/fonts/${slug}`,
    custom: false,
  })),
  {
    family: "sans-serif",
    label: "Sans-serif ของอุปกรณ์",
    weights: [],
    category: "system",
    custom: false,
  },
  {
    family: "serif",
    label: "Serif ของอุปกรณ์",
    weights: [],
    category: "system",
    custom: false,
  },
];
const names = new Set(builtInFonts.map((font) => font.family));
export const isBuiltInFont = (family) => names.has(family);
export const isSafeCustomFontFamily = (family) =>
  typeof family === "string" &&
  /^BSIGN Custom [0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(
    family,
  );
export const isAllowedFontFamily = (family) =>
  isBuiltInFont(family) || isSafeCustomFontFamily(family);
